// Step 1: Input Setup & Schema Validation
const items = $input.all();
const output = [];

for (const item of items) {
  const data = item.json.body || item.json;
  const requestId = data.request_id || `REQ-${Date.now()}`;
  const domain = (data.domain || '').trim();
  const legalName = (data.legal_name || '').trim();
  const region = (data.region || '').trim();
  const industry = (data.industry || 'Enterprise Software').trim();
  const employeeCount = data.employee_count !== undefined && data.employee_count !== null ? Number(data.employee_count) : null;
  const fundingStage = data.funding_stage || 'Unknown';
  const approved = data.approved === true;
  const websiteActive = data.website_active !== false;

  // Strict validation rules
  if (!domain || !domain.includes('.') || domain.split('.').length < 2) {
    throw new Error(`Invalid or missing domain: ${domain}`);
  }
  if (!legalName) {
    throw new Error('Missing mandatory field: legal_name');
  }
  if (!region) {
    throw new Error('Region cannot be empty');
  }
  if (employeeCount !== null && employeeCount < 0) {
    throw new Error(`Employee count cannot be negative: ${employeeCount}`);
  }

  output.push({
    json: {
      request_id: requestId,
      domain,
      legal_name: legalName,
      region,
      industry,
      employee_count: employeeCount,
      funding_stage: fundingStage,
      approved,
      website_active: websiteActive,
      stage: 'VALIDATED'
    }
  });
}

return output;

// Step 2: Named Sources & Provenance Extraction
const items = $input.all();
const output = [];
const now = new Date().toISOString();

for (const item of items) {
  const d = item.json;

  const provenance = {
    company_website: {
      source_id: "SRC-WEB-01",
      source_url: `https://${d.domain}`,
      extracted_at: now,
      raw_value: d.legal_name,
      source_type: "website"
    },
    business_directory: {
      source_id: "SRC-DIR-02",
      source_url: `https://bizregistry.org/lookup/${d.domain}`,
      extracted_at: now,
      raw_value: d.employee_count !== null ? String(d.employee_count) : "null",
      source_type: "web_directory"
    },
    legal_registry: {
      source_id: "SRC-REG-04",
      source_url: `https://corp-filings.gov/entity/${encodeURIComponent(d.legal_name)}`,
      extracted_at: now,
      raw_value: d.region,
      source_type: "registry"
    }
  };

  output.push({
    json: {
      ...d,
      provenance
    }
  });
}

return output;

// Step 3: Explicit Decision Rules & Deduplication Engine
const crypto = require('crypto');
const items = $input.all();
const output = [];

// Seeded CRM mock records for deduplication check
const existingCrmRecords = [
  {
    crm_id: 'CRMID-881',
    domain: 'acmesoftware.com',
    legal_name: 'Acme Software Solutions Inc.',
    region: 'North America',
    status: 'EXISTING_CUSTOMER'
  }
];

function normalizeDomain(d) {
  let dom = (d || '').toLowerCase().trim();
  for (const prefix of ['https://', 'http://', 'www.']) {
    if (dom.startsWith(prefix)) dom = dom.slice(prefix.length);
  }
  return dom.replace(/\/+$/, '');
}

function normalizeLegalName(name) {
  let n = (name || '').toLowerCase().trim();
  const suffixes = [', inc.', ' inc.', ' inc', ', llc', ' llc', ' corp.', ' corp', ' ltd.', ' ltd', ' systems', ' technologies'];
  for (const s of suffixes) {
    n = n.replace(s, '');
  }
  return n.trim();
}

for (const item of items) {
  const d = item.json;
  const normDomain = normalizeDomain(d.domain);
  const normName = normalizeLegalName(d.legal_name);

  // Idempotency Key calculation: hash(request_id : domain : legal_name)
  const idempotencyKey = crypto
    .createHash('sha256')
    .update(`${d.request_id}:${normDomain}:${normName}`)
    .digest('hex');

  // 1. Deduplication Check
  let collision = null;
  for (const rec of existingCrmRecords) {
    if (normalizeDomain(rec.domain) === normDomain) {
      collision = { type: 'domain', rec };
      break;
    }
    if (normalizeLegalName(rec.legal_name) === normName) {
      collision = { type: 'legal_name', rec };
      break;
    }
  }

  if (collision) {
    output.push({
      json: {
        lead_id: d.request_id,
        domain: d.domain,
        status: 'REJECTED',
        reason: `Deduplication collision on ${collision.type}: matches existing CRM record ${collision.rec.crm_id} (${collision.rec.legal_name})`,
        idempotency_key: idempotencyKey,
        provenance: d.provenance,
        verification_status: 'N/A',
        crm_id: null
      }
    });
    continue;
  }

  // 2. Missing Evidence Check (Uncertain State)
  if (d.employee_count === null || d.employee_count === undefined) {
    output.push({
      json: {
        lead_id: d.request_id,
        domain: d.domain,
        status: 'UNCERTAIN',
        reason: 'Missing verifiable evidence: employee_count not found in registry (SRC-DIR-02). Action withheld pending human manual review.',
        idempotency_key: idempotencyKey,
        provenance: d.provenance,
        verification_status: 'N/A',
        crm_id: null
      }
    });
    continue;
  }

  // 3. Qualification Criteria Scope Check
  const allowedRegions = ['north america', 'us', 'ca', 'canada', 'usa'];
  const regionNorm = d.region.toLowerCase().trim();
  const isRegionAllowed = allowedRegions.some(r => regionNorm.includes(r));

  if (d.employee_count < 50 || d.employee_count > 500) {
    output.push({
      json: {
        lead_id: d.request_id,
        domain: d.domain,
        status: 'REJECTED',
        reason: `Disqualified: Employee count ${d.employee_count} outside ICP bounds [50, 500]`,
        idempotency_key: idempotencyKey,
        provenance: d.provenance,
        verification_status: 'N/A',
        crm_id: null
      }
    });
    continue;
  }

  if (!isRegionAllowed) {
    output.push({
      json: {
        lead_id: d.request_id,
        domain: d.domain,
        status: 'REJECTED',
        reason: `Disqualified: Region '${d.region}' is outside allowed territories (North America)`,
        idempotency_key: idempotencyKey,
        provenance: d.provenance,
        verification_status: 'N/A',
        crm_id: null
      }
    });
    continue;
  }

  // Qualified Lead
  output.push({
    json: {
      ...d,
      lead_id: d.request_id,
      status: 'QUALIFIED',
      reason: 'Lead satisfies ICP criteria (50-500 employees, allowed region, active entity).',
      idempotency_key: idempotencyKey,
      proposed_action: {
        destination: 'HubSpot CRM Sandbox (Free Tier)',
        target_view: 'Private Research Leads (Sandbox View ID: HS-PRIV-VIEW-409)',
        action_type: 'UPSERT_PRIVATE_LEAD',
        payload: {
          properties: {
            domain: d.domain,
            name: d.legal_name,
            numberofemployees: d.employee_count,
            hs_lead_status: 'NEW_RESEARCH',
            hs_private_view: 'HS-PRIV-VIEW-409'
          }
        }
      }
    }
  });
}

return output;

// Pending Operator Approval branch
const item = $input.first().json;
return [{
  json: {
    lead_id: item.lead_id,
    status: 'QUALIFIED',
    reason: 'Lead qualified. Awaiting human operator approval before CRM load.',
    crm_id: null,
    verification_status: 'PENDING_REVIEW',
    idempotency_key: item.idempotency_key,
    proposed_action: item.proposed_action,
    provenance: item.provenance
  }
}];

// Step 4 & CRM Ingestion: Mock HubSpot Private View Loader with Idempotency Guard
const item = $input.first().json;

// Generate deterministic CRM ID based on domain
const cleanDomain = item.domain.replace(/[^a-zA-Z0-9]/g, '').slice(0, 8);
const crmId = `CRMID-101-${cleanDomain}`;

return [{
  json: {
    ...item,
    crm_id: crmId,
    crm_destination: 'HubSpot Free CRM Sandbox (HS-PRIV-VIEW-409)',
    loaded_at: new Date().toISOString()
  }
}];

// Step 5: Independent Post-Action Verification
const item = $input.first().json;

// Check domain resolution / simulated website active flag
const websiteActive = item.website_active !== false;
const httpStatus = websiteActive ? 200 : 404;
const websiteResolved = httpStatus === 200;

const verificationStatus = (item.crm_id && websiteResolved) ? 'VERIFIED_SUCCESS' : 'FAILED';

const verificationDetails = {
  target_record_id: item.crm_id,
  checked_url: `https://${item.domain}`,
  http_status: httpStatus,
  website_resolved: websiteResolved,
  intended_state: 'ACTIVE_AND_CRM_LOADED',
  observed_state: websiteResolved ? 'ACTIVE_AND_CRM_LOADED' : 'INACTIVE_WEBSITE_404',
  discrepancy_notes: websiteResolved ? null : 'Website returned HTTP 404; verification failed.'
};

return [{
  json: {
    lead_id: item.lead_id,
    domain: item.domain,
    status: item.status,
    reason: item.reason,
    crm_id: item.crm_id,
    idempotency_key: item.idempotency_key,
    verification_status: verificationStatus,
    verification_details: verificationDetails,
    provenance: item.provenance
  }
}];

// Merge non-qualified leads (Rejected / Uncertain)
const item = $input.first().json;
return [{ json: item }];
